    def test_01_sp_dpt_opn_010_success_saving_group_relation_empty(self, user):
        # data test
        customer_type='G'
        catalog_code_saving_group_relation_empty='CDMMK0000'
        catalog_name_saving_group_relation_empty='Call deposit account in MMK'
        deposit_type='Savings'
        deposit_sub_type='S4'
        im_banking=True
        pc_book=True
        sp_helper = StoredProcedureHelper(user)
        fields_data = sp_payload.DPT_OPN(
            customer_code=customer_code_enterprise,
            customer_type=customer_type,
            catalog_code=catalog_code_saving_group_relation_empty,
            catalog_name=catalog_name_saving_group_relation_empty,
            deposit_type=deposit_type,
            account_name=account_name_enterprise,
            description=description,
            deposit_sub_type=deposit_sub_type,
            reason_of_account_opening=reason_of_account_opening,
            im_banking=im_banking,
            pc_book=pc_book
        )
        rs = sp_helper.DPT_OPN(fields_data)
        step_code = 'DPT_OPN'
        data_actual = RU.get_p2_content_response_by_step_code(rs, step_code)
        print(json.dumps(data_actual, indent=4, sort_keys=False))
        # verify key response level 1
        AU.assert_exists(expected_key['level_01'], data_actual)
        # get value in level 1
        value_status = data_actual['status']
        value_error_message = data_actual['error_message']
        value_error_code = data_actual['error_code']
        value_data = data_actual['data']
        # verify value of key response in level 1
