    def test_01_sp_dpt_opn_011_success_saving_group_relation_not_empty(self, user):
        # data test
        customer_type='G'
        catalog_code_saving_group_relation_not_empty='SAMMK0000'
        catalog_name_saving_group_relation_not_empty='Savings account in MMK'
        deposit_type='Savings'
        deposit_sub_type='S1'
        im_banking=True
        pc_book=True
        relation_customers = [
            "11001706",
            "11001707",
            "11001708",
            "11001709"
        ]
        sp_helper = StoredProcedureHelper(user)
        fields_data = sp_payload.DPT_OPN(
            customer_code=customer_code_enterprise,
            customer_type=customer_type,
            catalog_code=catalog_code_saving_group_relation_not_empty,
            catalog_name=catalog_name_saving_group_relation_not_empty,
            deposit_type=deposit_type,
            account_name=account_name_enterprise,
            description=description,
            deposit_sub_type=deposit_sub_type,
            reason_of_account_opening=reason_of_account_opening,
            im_banking=im_banking,
            pc_book=pc_book,
            relation_customers=relation_customers
        )
        rs = sp_helper.DPT_OPN(fields_data)
        step_code = 'DPT_OPN'
        data_actual = RU.get_p2_content_response_by_step_code(rs, step_code)
        print(json.dumps(data_actual, indent=4, sort_keys=False))
        # verify key response level 1
