    def test_01_sp_dpt_opn_013_success_fixed_deposit_single_principal_plus_interest_rollover(self, user):
        # data test
        catalog_code_fixed_deposit_single_principal_plus_interest_rollover='FD06PIMMK'
        catalog_name_fixed_deposit_single_principal_plus_interest_rollover='Fixed deposit 6 months (Principal plus interest rollover) in MMK'
        deposit_type='Fixed Deposit'
        deposit_sub_type='T3'
        deposit_purpose='S'
        rollover='A'
        auto_transfer_option='N'
        sp_helper = StoredProcedureHelper(user)
        fields_data = sp_payload.DPT_OPN(
            customer_code=customer_code_individual,
            catalog_code=catalog_code_fixed_deposit_single_principal_plus_interest_rollover,
            catalog_name=catalog_name_fixed_deposit_single_principal_plus_interest_rollover,
            deposit_type=deposit_type,
            account_name=account_name_individual,
            description=description,
            deposit_sub_type=deposit_sub_type,
            reason_of_account_opening=reason_of_account_opening,
            deposit_purpose=deposit_purpose,
            rollover=rollover,
            auto_transfer_option=auto_transfer_option
        )
        rs = sp_helper.DPT_OPN(fields_data)
        step_code = 'DPT_OPN'
        data_actual = RU.get_p2_content_response_by_step_code(rs, step_code)
        print(json.dumps(data_actual, indent=4, sort_keys=False))
        # verify key response level 1
        AU.assert_exists(expected_key['level_01'], data_actual)
        # get value in level 1
