    def test_01_sp_dpt_opn_015_success_fixed_deposit_linkage_relation_empty(self, user):
        # data test
        customer_type='L'
        catalog_code_fixed_deposit_linkage_relation_empty='FD03NRMMK'
        catalog_name_fixed_deposit_linkage_relation_empty='Fixed deposit 3 months (No rollover) in MMK'
        deposit_type='Fixed Deposit'
        deposit_sub_type='T2'
        deposit_purpose='S'
        rollover='N'
        auto_transfer_option='A'
        sp_helper = StoredProcedureHelper(user)
        fields_data = sp_payload.DPT_OPN(
            customer_code=customer_code_individual,
            customer_type=customer_type,
            catalog_code=catalog_code_fixed_deposit_linkage_relation_empty,
            catalog_name=catalog_name_fixed_deposit_linkage_relation_empty,
            deposit_type=deposit_type,
            account_name=account_name_individual,
            description=description,
            deposit_sub_type=deposit_sub_type,
            reason_of_account_opening=reason_of_account_opening,
            deposit_purpose=deposit_purpose,
            rollover=rollover,
            auto_transfer_option=auto_transfer_option,
            to_account_number=to_account_number_saving_linkage_valid
        )
        rs = sp_helper.DPT_OPN(fields_data)
        step_code = 'DPT_OPN'
        data_actual = RU.get_p2_content_response_by_step_code(rs, step_code)
        print(json.dumps(data_actual, indent=4, sort_keys=False))
        # verify key response level 1
        AU.assert_exists(expected_key['level_01'], data_actual)
