        # data test
        customer_type='G'
        catalog_code_fixed_deposit_group_relation_not_empty='FD09PIMMK'
        catalog_name_fixed_deposit_group_relation_not_empty='Fixed deposit 9 months (Principal plus interest rollover) in MMK'
        deposit_type='Fixed Deposit'
        deposit_sub_type='T4'
        deposit_purpose='S'
        rollover='A'
        auto_transfer_option='N'
