    def test_01_sp_dpt_opn_020_success_prepaid_fixed_deposit_single_principal_rollover_only(self, user):
        # data test
        catalog_code_prepaid_fixed_deposit_single_principal_rollover_only='PR007MMK0'
        catalog_name_prepaid_fixed_deposit_single_principal_rollover_only='Prepaid Fixed Deposit (7 days)'
        deposit_type='Fixed Deposit'
        deposit_sub_type='T6'
        deposit_purpose='S'
        rollover='P'
        auto_transfer_option='I'
        sp_helper = StoredProcedureHelper(user)
        fields_data = sp_payload.DPT_OPN(
            customer_code=customer_code_individual,
            catalog_code=catalog_code_prepaid_fixed_deposit_single_principal_rollover_only,
            catalog_name=catalog_name_prepaid_fixed_deposit_single_principal_rollover_only,
            deposit_type=deposit_type,
            account_name=account_name_individual,
            description=description,
            deposit_sub_type=deposit_sub_type,
            reason_of_account_opening=reason_of_account_opening,
            deposit_purpose=deposit_purpose,
            rollover=rollover,
            auto_transfer_option=auto_transfer_option,
            to_account_number=to_account_number_current_single_valid
        )
        rs = sp_helper.DPT_OPN(fields_data)
        step_code = 'DPT_OPN'
        data_actual = RU.get_p2_content_response_by_step_code(rs, step_code)
        print(json.dumps(data_actual, indent=4, sort_keys=False))
