        # data test
        catalog_code='FD09NRMMK'
        catalog_name='Fixed deposit 9 months (No rollover) in MMK'
        deposit_type='Fixed Deposit'
        deposit_sub_type='T4'
        deposit_purpose='S'
        rollover='N'
        auto_transfer_option='A'
