        # get value in level 1
        value_status = data_actual_02['status']
        value_error_message = data_actual_02['error_message']
        value_error_code = data_actual_02['error_code']
        value_data = data_actual_02['data']
        # verify value of key response in level 1
        AU.assert_equals('status', 1, value_status)
        AU.assert_equals('error_message', f'Invalid account number [{to_account_number_saving_group_valid}]', value_error_message)
        AU.assert_equals('error_code', 'ERROR', value_error_code)
        AU.assert_not_null('data', value_data)
        AU.assert_not_empty('data', value_data)
        # case 3: not same customer code, customer type 'Single customer' same customer type 'Single customer'
